use std::env;
use std::io::{self, BufRead, IsTerminal, Write};
use std::process;

const HOW_TO: &str = "Type something like 7 + 5";
const RANGE: &str = "Use whole numbers from 0 to 350";

enum Token<'a> {
    Number(&'a str),
    Op(char),
}

// this is the function that does the thing
fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if !args.is_empty() {
        match solve(&args.join(" ")) {
            Ok(result) => println!("{result}"),
            Err(message) => {
                eprintln!("{message}");
                process::exit(1);
            }
        }
        return;
    }
    let stdin = io::stdin();
    let interactive = stdin.is_terminal();
    let mut lines = stdin.lock().lines();
    loop {
        if interactive {
            print!("> ");
            let _ = io::stdout().flush();
        }
        let Some(Ok(line)) = lines.next() else {
            if interactive {
                println!();
            }
            break;
        };
        let input = line.trim();
        if input.is_empty() {
            continue;
        }
        if matches!(input, "q" | "quit" | "exit") {
            break;
        }
        match solve(input) {
            Ok(result) => println!("{result}"),
            Err(message) => println!("{message}"),
        }
    }
}

fn solve(input: &str) -> Result<&'static str, &'static str> {
    let tokens = tokenize(input).ok_or(HOW_TO)?;
    let [Token::Number(a), Token::Op(op), Token::Number(b)] = tokens[..] else {
        return Err(HOW_TO);
    };
    let (Some(a), Some(b)) = (number(a), number(b)) else {
        return Err(RANGE);
    };
    answer(a, op, b).ok_or(HOW_TO)
}

fn tokenize(input: &str) -> Option<Vec<Token<'_>>> {
    let mut tokens = Vec::new();
    let mut rest = input.trim_start();
    while let Some(c) = rest.chars().next() {
        if c.is_ascii_digit() {
            let end = rest
                .find(|ch: char| !ch.is_ascii_digit())
                .unwrap_or(rest.len());
            tokens.push(Token::Number(&rest[..end]));
            rest = &rest[end..];
        } else {
            let op = match c {
                '+' => '+',
                '-' | '−' => '-',
                '*' | 'x' | 'X' | '×' => '*',
                '/' | '÷' => '/',
                _ => return None,
            };
            tokens.push(Token::Op(op));
            rest = &rest[c.len_utf8()..];
        }
        rest = rest.trim_start();
    }
    Some(tokens)
}

