fn answer(a: u32, op: char, b: u32) -> Option<&'static str> {
    match op {
        '+' => add(a, b),
        '-' => subtract(a, b),
        '*' => multiply(a, b),
        '/' => divide(a, b),
        _ => None,
    }
}

